create table if not exists public.rank_products(id text primary key,slug text unique not null,name text not null,price_inr integer not null check(price_inr>=0),billing_label text not null default '/ month',description text,perks jsonb not null default '[]'::jsonb,featured boolean not null default false,active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table if not exists public.rank_orders(id uuid primary key default gen_random_uuid(),rank_product_id text not null references public.rank_products(id),minecraft_ign text not null check(minecraft_ign~'^[A-Za-z0-9_]{3,16}$'),discord_username text,email text not null,payment_status text not null default 'pending' check(payment_status in('pending','paid','failed','refunded')),fulfillment_status text not null default 'pending' check(fulfillment_status in('pending','processing','fulfilled','cancelled')),payment_reference text,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.rank_products enable row level security;alter table public.rank_orders enable row level security;drop policy if exists "public read active ranks" on public.rank_products;create policy "public read active ranks" on public.rank_products for select to anon,authenticated using(active=true);drop policy if exists "public create rank orders" on public.rank_orders;create policy "public create rank orders" on public.rank_orders for insert to anon,authenticated with check(payment_status='pending' and fulfillment_status='pending' and exists(select 1 from public.rank_products rp where rp.id=rank_product_id and rp.active=true));grant select on public.rank_products to anon,authenticated;grant insert on public.rank_orders to anon,authenticated;revoke select,update,delete on public.rank_orders from anon,authenticated;create index if not exists rank_orders_rank_product_id_idx on public.rank_orders(rank_product_id);create index if not exists rank_orders_created_at_idx on public.rank_orders(created_at desc);create index if not exists rank_orders_status_idx on public.rank_orders(payment_status,fulfillment_status);insert into public.rank_products(id,slug,name,price_inr,billing_label,description,perks,featured,active,sort_order) values('vip','vip','VIP',49,'/ month','Your first upgrade.','["VIP chat prefix","Exclusive VIP perks","Priority support"]',false,true,1),('vip_plus','vip-plus','VIP+',99,'/ month','More perks, more presence.','["Everything in VIP","VIP+ cosmetics","Higher priority support"]',false,true,2),('mvp','mvp','MVP',149,'/ month','The top donor rank currently available.','["Everything in VIP+","/fly while supported by the server","MVP cosmetics & perks"]',true,true,3) on conflict(id) do update set slug=excluded.slug,name=excluded.name,price_inr=excluded.price_inr,billing_label=excluded.billing_label,description=excluded.description,perks=excluded.perks,featured=excluded.featured,active=excluded.active,sort_order=excluded.sort_order,updated_at=now();